const connectionState = () => state.view?.connectedAccounts && !Array.isArray(state.view.connectedAccounts) ? state.view.connectedAccounts : {definitions:[],items:[]};
const connectionDefinition = provider => arr(connectionState().definitions).find(item => item.provider === provider);
