function outcomesPage() { const outcomes=arr(state.view?.operatingOutcomes).filter(outcome=>outcome.objective||outcome.plan||outcome.graph||outcome.nodes); return `${pageHeading('Choose substantial work with a visible mandate.','Define the objective and operating limits once. MIDAS can prepare supported internal work; account access, paid model work, and external effects remain separate.',button('Create outcome mandate','outcome-create'))}${outcomes.length?`<div class="outcomes-stack section-spacer">${outcomes.map(outcomeCard).join('')}</div>`:`<section class="panel empty-state"><div class="empty-illustration">01</div><h3>Start with one finishable objective.</h3><p>Describe the business result you want, then inspect the worker plan, its evidence, and the exact owner decision before work proceeds.</p>${button('Create outcome mandate','outcome-create','', 'secondary')}</section>`}`; }
function outcomeCreateDialog() { openDialog('Create an outcome mandate',`<p class="dialog-intro">Start with the result you need and how much preparation you want delegated. A mandate prepares local work only; it never authorizes a live model call, account action, customer communication, spending, or publication.</p><form data-form="outcome-create"><div class="form-grid"><div class="form-field"><label for="outcome-objective">What outcome do you need?</label><textarea id="outcome-objective" name="objective" minlength="8" maxlength="2000" required placeholder="e.g. Prepare a current, evidence-backed offer clarification and the local drafts needed for owner review."></textarea><span class="field-help">State a finish line the owner can inspect.</span></div><fieldset class="evidence-selection outcome-autonomy"><legend>How much preparation can MIDAS do?</legend><label class="choice"><input type="radio" name="autonomy" value="propose_only" checked><span><strong>Bring me a plan first</strong><small>Prepare a bounded worker plan for owner selection.</small></span></label><label class="choice"><input type="radio" name="autonomy" value="prepare_supported_work"><span><strong>Prepare supported local work</strong><small>After a valid plan, create only the local reviewable work it permits.</small></span></label></fieldset><fieldset class="evidence-selection"><legend>Supported jobs for this mandate</legend><p class="field-help">Choose only the local jobs this outcome may use. You can narrow these later by creating a new mandate.</p><div class="job-choice-grid"><label class="check-label"><input type="checkbox" name="allowedFamilies" value="response-packet" checked><span><strong>Evidence-backed response or offer packet</strong><small>Local drafts, missing-information checklist, and review notes.</small></span></label><label class="check-label"><input type="checkbox" name="allowedFamilies" value="business-site" checked><span><strong>Contained business website</strong><small>A local inquiry experience to inspect; publishing stays separate.</small></span></label><label class="check-label"><input type="checkbox" name="allowedFamilies" value="campaign-packet"><span><strong>Campaign packet</strong><small>Coordinated offer, creative, and follow-up drafts.</small></span></label><label class="check-label"><input type="checkbox" name="allowedFamilies" value="marketing-page"><span><strong>Marketing page</strong><small>A local page that follows a supported campaign packet.</small></span></label><label class="check-label"><input type="checkbox" name="allowedFamilies" value="functional-project"><span><strong>Functional local project</strong><small>Bounded local interface and declarative data schema, with checks.</small></span></label></div></fieldset><details class="advanced-limits"><summary>Advanced resource limits <span class="optional">finite local planning ceilings</span></summary><p class="field-help">These are planning ceilings, not a permission for a paid or live model call. The server enforces them.</p><div class="form-grid two-up"><div class="form-field"><label for="outcome-calls">Maximum planned calls</label><input id="outcome-calls" name="maxCalls" type="number" min="4" max="64" step="1" value="33" required></div><div class="form-field"><label for="outcome-repair">Repair reserve</label><input id="outcome-repair" name="repairReserve" type="number" min="0" max="60" step="1" value="12" required><span class="field-help">Held back for an owner-requested correction.</span></div></div></details></div><div class="form-footer"><button class="button" type="submit">Create outcome mandate</button></div></form>`,'outcome-create'); }
